import { Injectable } from '@angular/core';
import { mPageService } from '@clinicaloffice/clinical-office-mpage-core';

/** Shape of the NativeToWebAuthBridge GetCernerAccessToken response. */
interface CernerAccessTokenResponse {
  access_token?: string;
  expires_in?: number;
  success_ind?: boolean;
  error_code?: string;
  diagnostic_text?: string;
  tenant_id?: string;
  token_type?: string;
}

/**
 * @class CernerTokenService
 * @description Acquires and caches a Cerner access token from the PowerChart
 * NativeToWebAuthBridge via `window.external.DiscernObjectFactory('NATIVETOWEBAUTHBRIDGE')`
 * — the same direct COM-factory pattern CernerActionService uses for PVVIEWERMPAGE etc.
 *
 * COMPASS is not hosted as a Cerner workflow MPage, so the MPages platform
 * wrapper (`CERN_Platform.getWrappedDiscernObject`) is not injected into the
 * page. That wrapper is only a thin proxy around the same DiscernObjectFactory
 * call (see mpage_archive MPAGES_9_2 master-components.js — getDiscernObject
 * returns `window.external.DiscernObjectFactory(objectName)` and invoke()
 * dispatches the method directly on the returned COM proxy), so calling the
 * factory directly is equivalent.
 *
 * The token is fetched once and reused until it expires (the bridge returns
 * `expires_in` seconds, typically ~10 minutes). A safety buffer is subtracted so
 * a token is never handed out within a minute of expiry. Concurrent callers
 * share a single in-flight bridge invocation.
 *
 * Outside PowerChart (local dev) the factory is unavailable and
 * getAccessToken() resolves to an empty string — callers should treat an empty
 * token as "no live API access" and degrade gracefully (the CCL backend falls
 * back to mock suggestions when no token is supplied).
 */
@Injectable({ providedIn: 'root' })
export class CernerTokenService {
  /** App identity registered with the bridge (same values proven in cov-mpage-sandbox). */
  private static readonly APP_ID = '3202020';
  private static readonly APP_NAME = 'MPages Platform Application';
  /** Refuse to reuse a token within this many ms of its expiry. */
  private static readonly EXPIRY_BUFFER_MS = 60_000;

  private cachedToken = '';
  private tokenExpiresAt = 0; // epoch ms; 0 = nothing cached
  private inFlight: Promise<string> | null = null;

  constructor(private mPage: mPageService) {}

  /**
   * Returns a valid Cerner access token, fetching a new one from the native
   * bridge only when the cached token is missing or about to expire.
   * Resolves to '' when the bridge is unavailable or the call fails.
   */
  getAccessToken(): Promise<string> {
    if (this.cachedToken && Date.now() < this.tokenExpiresAt - CernerTokenService.EXPIRY_BUFFER_MS) {
      return Promise.resolve(this.cachedToken);
    }
    if (!this.inFlight) {
      this.inFlight = this.fetchToken().finally(() => {
        this.inFlight = null;
      });
    }
    return this.inFlight;
  }

  /** Drops the cached token so the next getAccessToken() refetches. */
  clearToken(): void {
    this.cachedToken = '';
    this.tokenExpiresAt = 0;
  }

  /** Invokes GetCernerAccessToken on the native bridge and caches the result. */
  private async fetchToken(): Promise<string> {
    try {
      const external = (window as any).external;
      if (!external || typeof external.DiscernObjectFactory !== 'function') {
        this.log('DiscernObjectFactory unavailable — no access token (local dev?)');
        return '';
      }

      // In the Edge webview the factory and the COM method both return promises;
      // in the legacy embedded browser they resolve synchronously — await covers both.
      const bridge = await external.DiscernObjectFactory('NATIVETOWEBAUTHBRIDGE');
      if (!bridge) {
        this.log('NATIVETOWEBAUTHBRIDGE could not be created');
        return '';
      }

      const correlationId = new Date().toISOString();
      const raw = await bridge.GetCernerAccessToken(
        CernerTokenService.APP_ID,
        CernerTokenService.APP_NAME,
        correlationId,
      );
      const parsed: CernerAccessTokenResponse = JSON.parse(raw);

      if (parsed.success_ind === false || !parsed.access_token) {
        this.log(`GetCernerAccessToken failed: ${parsed.error_code || 'no access_token'}`
          + (parsed.diagnostic_text ? ` — ${parsed.diagnostic_text}` : ''));
        return '';
      }

      this.cachedToken = parsed.access_token;
      const ttlSeconds = typeof parsed.expires_in === 'number' && parsed.expires_in > 0
        ? parsed.expires_in
        : 300; // conservative default if the bridge omits expires_in
      this.tokenExpiresAt = Date.now() + ttlSeconds * 1000;
      this.log(`Cerner access token acquired (expires in ${ttlSeconds}s)`);
      return this.cachedToken;
    } catch (err: any) {
      this.log('GetCernerAccessToken threw: ' + (err?.message || String(err)));
      return '';
    }
  }

  private log(message: string): void {
    try {
      this.mPage.putLog('[CernerTokenService] ' + message);
    } catch {
      // mPage may not be wired up during local dev — ignore.
    }
  }
}
