import { ChangeDetectionStrategy, Component, EventEmitter, Input, Output } from '@angular/core';
import { DocumentRow, SuggestedDocumentRow } from '../../../../../../../models/document.model';

/**
 * Presentational box showing AI-suggested documents for a worklist item.
 * Behaves like the Available Documents table (a curated subset): rows share the
 * parent's `selectedDocuments` Set and emit select/preview events the parent
 * wires to its existing handlers. Attaching is done via the parent's existing
 * "Save Attachments" button.
 */
@Component({
  selector: 'app-suggested-documents',
  templateUrl: './suggested-documents.component.html',
  styleUrls: ['./suggested-documents.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SuggestedDocumentsComponent {
  /** Curated suggestions, already matched to document rows with justification. */
  @Input() suggestions: SuggestedDocumentRow[] = [];
  /**
   * True once the suggestions call has completed. Until then the box stays
   * hidden; afterwards an empty list renders a "no suggested documents" message
   * (a real possible response from the Oracle API) instead of disappearing.
   */
  @Input() loaded = false;
  /** Shared selection set owned by the parent DocumentSelectionComponent. */
  @Input() selectedDocuments: Set<number | string> = new Set<number | string>();

  /** Emitted when a suggestion checkbox toggles. */
  @Output() toggleSelect = new EventEmitter<{ doc: DocumentRow; checked: boolean }>();
  /** Emitted when a suggestion row is chosen for preview. */
  @Output() preview = new EventEmitter<DocumentRow>();

  /** trackBy for the suggestions list. */
  trackByEventId(_index: number, doc: SuggestedDocumentRow): number | string {
    return doc.eventId;
  }

  /** Whether a suggestion is currently in the shared selection set. */
  isChecked(doc: SuggestedDocumentRow): boolean {
    return this.selectedDocuments.has(doc.eventId);
  }

  /** Handle a checkbox change; let the parent mutate the shared set. */
  onToggle(doc: SuggestedDocumentRow, checked: boolean): void {
    this.toggleSelect.emit({ doc, checked });
  }

  /** Request a preview of the given suggestion. */
  previewRow(doc: SuggestedDocumentRow): void {
    this.preview.emit(doc);
  }
}
