import { ChangeDetectionStrategy, Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { FilterSet } from '../../../../models/compass-configuration.model';

export interface LocationPatch {
  id?: string;
  label?: string;
  sortOrder?: number;
  isDefault?: number;
  dataElement?: string;
  options?: string[]; // bare string array — wire layer converts to FilterSetOption[]
}

export interface MappingPatch {
  source: string; // first option string from the location filter
  target: string; // facility display
  previousSource?: string; // what the source was before this change — parent uses this to find the existing row
}

@Component({
  selector: 'app-location-editor',
  templateUrl: './location-editor.component.html',
  styleUrls: ['./location-editor.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class LocationEditorComponent implements OnChanges {
  @Input() location: FilterSet | null = null;
  @Input() mapping: MappingPatch | null = null;
  @Input() dataElementOptions: string[] = ['schedulingLocation', 'orderingLocation'];

  // Validation messages — surfaced inline next to each field by the parent.
  @Input() idError: string | null = null;
  @Input() labelError: string | null = null;
  @Input() optionsError: string | null = null;
  @Input() mappingError: string | null = null;

  @Output() patch = new EventEmitter<LocationPatch>();
  @Output() mappingChange = new EventEmitter<MappingPatch | null>();
  @Output() delete = new EventEmitter<void>();

  showMapping = false;

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['location']) {
      this.showMapping = false;
    }
  }

  trackByIndex(index: number): number {
    return index;
  }

  onIdChange(value: string): void { this.patch.emit({ id: value }); }
  onLabelChange(value: string): void { this.patch.emit({ label: value }); }
  onSortOrderChange(value: number): void { this.patch.emit({ sortOrder: Number(value) || 0 }); }
  onDefaultChange(value: boolean): void { this.patch.emit({ isDefault: value ? 1 : 0 }); }
  onDataElementChange(value: string): void { this.patch.emit({ dataElement: value }); }

  onOptionChange(index: number, value: string): void {
    const opts = this.location?.filters?.[0]?.options ?? [];
    const next = opts.map(o => o?.item ?? '');
    next[index] = value;
    this.patch.emit({ options: next });
  }
  addOption(): void {
    const opts = this.location?.filters?.[0]?.options ?? [];
    const next = [...opts.map(o => o?.item ?? ''), ''];
    this.patch.emit({ options: next });
  }
  removeOption(index: number): void {
    const opts = this.location?.filters?.[0]?.options ?? [];
    const next = opts.map(o => o?.item ?? '');
    next.splice(index, 1);
    this.patch.emit({ options: next });
  }

  toggleMapping(): void {
    this.showMapping = !this.showMapping;
    // Hide is non-destructive. Removing a mapping requires clicking the explicit "Remove" button.
  }
  removeMapping(): void {
    this.mappingChange.emit(null);
  }
  onMappingSourceChange(value: string): void {
    this.mappingChange.emit({
      source: value,
      target: this.mapping?.target ?? '',
      previousSource: this.mapping?.source
    });
  }
  onMappingTargetChange(value: string): void {
    this.mappingChange.emit({
      source: this.mapping?.source ?? '',
      target: value,
      previousSource: this.mapping?.source
    });
  }

  onDelete(): void { this.delete.emit(); }
}
